// رسالة واردة من محادثة فردية فقط (لا الرسائل المرسلة منا ولا المجموعات): نص، أو صورة (لكشف الدوام)
const body = $input.first().json.body || $input.first().json;
const d = body.data || {};
const key = d.key || {};
if (key.fromMe) return [];
let jid = key.remoteJid || '';
if (jid.endsWith('@g.us') || jid === 'status@broadcast') return [];
// في بعض الإصدارات يأتي المعرّف بصيغة @lid والرقم الحقيقي في حقل آخر
if (jid.endsWith('@lid')) jid = key.senderPn || key.remoteJidAlt || key.participantAlt || d.senderPn || d.remoteJidAlt || jid;
if (String(jid).endsWith('@lid')) throw new Error('وصل المرسل بمعرّف @lid دون رقم الجوال: ' + JSON.stringify(key));
const phone = String(jid).split('@')[0].replace(/[^0-9]/g, '');
// الرسائل المؤقتة والمعدّلة والمقتبسة تأتي مغلّفة؛ يُستخرج النص من داخلها
let m = d.message || {};
for (let i = 0; i < 4; i++) {
  const inner = (m.ephemeralMessage || m.viewOnceMessage || m.viewOnceMessageV2 || m.documentWithCaptionMessage || {}).message
    || (m.editedMessage && (m.editedMessage.message || {}).protocolMessage && m.editedMessage.message.protocolMessage.editedMessage)
    || (m.protocolMessage && m.protocolMessage.editedMessage);
  if (!inner) break;
  m = inner;
}
// الرد يخرج من الـ instance نفسه الذي استقبل الرسالة
const instance = body.instance || 'ThirdPillar';
if (!phone) return [];
const img = m.imageMessage;
if (img) {
  return [{ json: { phone, text: (img.caption || '').trim(), instance, image: true, msgId: key.id || '', mimetype: img.mimetype || 'image/jpeg',
    base64: (d.message && d.message.base64) || m.base64 || '' } }];
}
const text = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || d.text || '';
if (!text.trim()) return [];
return [{ json: { phone, text: text.trim(), instance, image: false } }];

// خطأ من قاعدة البيانات (مثل مفتاح n8n غير مطابق) يظهر أحمر في سجل التنفيذ
const res = $input.first().json;
if (res.error) throw new Error(res.error);
// الرد الفارغ: لا يُرسل شيء. سبب ذلك في res.note (رقم غير مسجَّل، أو رسالة خارج محادثة الغياب)
const reply = (res.reply || '').trim();
if (!reply) return [{ json: { skipped: res.note || 'لا رد من بوت الغياب' } }];
const src = $('استخراج الرقم والنص').first().json;
return [{ json: { number: src.phone, text: reply, instance: src.instance } }];

// رد محادثة الدوام
const res = $input.first().json;
if (res.error) throw new Error(res.error);
const reply = (res.reply || '').trim();
if (!reply) return [];
const src = $('استخراج الرقم والنص').first().json;
return [{ json: { number: src.phone, text: reply, instance: src.instance } }];

// صورة كشف الدوام: من مرسل مسموح ينتظر البوت صورته فقط (غير ذلك تُتجاهل الصورة بصمت)
const src = $input.first().json;
const PUB = 'sb_publishable_mQliqX3dKgwlKsm-u1X_gQ_8TINNIrr', K = $('المفاتيح').first().json.keys, BOT = K.BOT, EVO_KEY = K.EVO;
const sbHeaders = { apikey: PUB, Authorization: 'Bearer ' + PUB, 'Content-Type': 'application/json' };
const ok = await this.helpers.httpRequest({ method: 'POST', url: 'https://wvklhyjtzqomiyhzsfuf.supabase.co/rest/v1/rpc/staff_bot_image', headers: sbHeaders, body: { p_key: BOT, p_phone: src.phone }, json: true });
if (ok.error) throw new Error(ok.error);
// غير مسموح: لا رد (السبب يظهر في مخرجات هذه العقدة). مسموح لكن لم يبدأ بـ«دوام»: يُذكَّر
if (!ok.ok) return [{ json: ok.allowed ? { number: src.phone, text: ok.note, instance: src.instance } : { skipped: ok.note || 'تُتجاهل الصورة' } }];
const say = (text) => this.helpers.httpRequest({ method: 'POST', url: 'https://evolution.ahmedhammad.page/message/sendText/' + encodeURIComponent(src.instance),
  headers: { apikey: EVO_KEY, 'Content-Type': 'application/json' }, body: { number: src.phone, text }, json: true });
await say('وصلت الصورة، جارٍ قراءة الكشف… (قد تستغرق دقيقة)');
// الصورة نفسها: من الرسالة إن أرسلها Evolution معها، وإلا تُطلب منه
let b64 = src.base64, mime = String(src.mimetype || 'image/jpeg').split(';')[0];
if (!b64) {
  const media = await this.helpers.httpRequest({ method: 'POST', url: 'https://evolution.ahmedhammad.page/chat/getBase64FromMediaMessage/' + encodeURIComponent(src.instance),
    headers: { apikey: EVO_KEY, 'Content-Type': 'application/json' }, body: { message: { key: { id: src.msgId } }, convertToMp4: false }, json: true });
  b64 = media.base64 || '';
  if (media.mimetype) mime = String(media.mimetype).split(';')[0];
}
if (!b64) { await say('تعذر استلام الصورة. أرسلها مرة أخرى.'); throw new Error('لم تُجلب صورة الرسالة من Evolution'); }
if (!['image/jpeg', 'image/png', 'image/webp'].includes(mime)) mime = 'image/jpeg';
let res;
try {
  res = await this.helpers.httpRequest({ method: 'POST', url: 'https://wvklhyjtzqomiyhzsfuf.supabase.co/functions/v1/read-staff-sheet', headers: sbHeaders, json: true, timeout: 180000,
    body: { bot_key: BOT, phone: src.phone, file: { media_type: mime, data: b64 } } });
} catch (e) {
  await say('تعذرت قراءة الكشف الآن. أرسل الصورة مرة أخرى بعد قليل، أو ارفعها من شاشة «دوام الموظفين» في الموقع.');
  throw e;
}
if (res.ignored) return [{ json: { skipped: 'تُتجاهل الصورة (الرقم ليس بانتظار كشف)' } }];
if (res.error) { await say('تعذرت قراءة الكشف: ' + res.error); throw new Error(res.error); }
return [{ json: { number: src.phone, text: res.reply, instance: src.instance } }];

// ضع المفتاحين هنا فقط، بين علامتي التنصيص:
// BOT: من الموقع ← «الإعدادات والمستخدمون» ← «مفتاح n8n (بوت الواتساب)» ← «نسخ المفتاح»
// EVO: مفتاح Evolution API (نفسه الذي في بوت الغياب القديم)
const BOT = 'PUT_BOT_KEY_HERE';
const EVO = 'PUT_EVOLUTION_API_KEY';
if (BOT.indexOf('PUT_') === 0 || EVO.indexOf('PUT_') === 0) throw new Error('ضع المفتاحين في عقدة «المفاتيح» أولًا');
return $input.all().map((i) => ({ json: Object.assign({}, i.json, { keys: { BOT, EVO } }) }));
